    "query": "late self assessment  penalties and next steps",
    "answer": "If the filing or payment deadline has already passed, move quickly: submit the return you still owe, pay what you can, and read any HMRC penalty notice carefully. Penalties can stack. Waiting rarely makes them smaller.",
