    "slug": "landlord-mortgage-interest-tax-relief",
    "metaTitle": "Landlord Mortgage Interest: How Tax Relief Works | TaxSimba",
    "metaDescription": "Understand residential landlord mortgage interest relief, separate interest from capital repayments and prepare records for the basic-rate tax reduction.",
    "dek": "Understand residential landlord mortgage interest relief, separate interest from capital repayments and prepare records for the basic-rate tax reduction.",
    "query": "landlord mortgage interest  how tax relief works",
    "answer": "If you still think residential mortgage interest comes off rental profit pound for pound, the rules have moved on. For individual landlords of residential property, finance-cost relief is restricted to a basic-rate Income Tax reduction. GOV.UK’s transition finished from 6 April 2020, so the older style of full deduction from profit no longer applies for those residential finance costs.",
    "alt": "A landlord separates mortgage interest paperwork from a property-profit ledger, house keys visible.",
    "details": [
      "Obtain the lender's breakdown and exclude capital repayments from the interest figure.",
      "Confirm the owner and use of borrowing before applying the residential restriction.",
      "Bring the carry-forward schedule so relief is considered consistently."
    ],
    "checklist": [
      "Interest or repayment of borrowed capital?",
      "Individual residential let or another structure?",
      "Any unused finance costs from earlier years?"
    ],
    "contentUpdatedAt": "2026-10-21T05:31:14.467Z",
    "depth": {
      "exampleTitle": "The lender's breakdown matters",
      "example": [
        "Jo's mortgage payments total £10,800 for the year, including £6,900 interest and £3,900 capital repayment. She supplies the interest certificate rather than claiming £10,800 as an expense. For an individual residential landlord, restricted finance costs are considered under the tax-reduction rules, with limits and possible carry-forward. The £6,900 is therefore an input to a relief calculation, not an automatic deduction from rent or a guaranteed cash refund."
      ],
      "decisionRows": [
        [
          "Interest or repayment of borrowed capital?",
          "Obtain the lender's breakdown and exclude capital repayments from the interest figure."
        ],
        [
          "Individual residential let or another structure?",
          "Confirm the owner and use of borrowing before applying the residential restriction."
        ],
        [
          "Any unused finance costs from earlier years?",
          "Bring the carry-forward schedule so relief is considered consistently."
        ]
      ],
      "questions": [
        [
          "Is relief always 20% of everything paid to the lender?",
          "No. Capital repayments do not qualify as interest and the finance-cost reduction is subject to statutory limits. Supply the detailed figures."
        ],
        [
          "Does the borrowing have to be on the rented property's mortgage?",
          "The purpose and use of borrowing matter. Provide the loan history and how funds were used rather than deciding from the security alone."
        ]
      ],
      "worksheetPrompts": [
        "Collect annual interest and fee statements.",
        "Separate interest from capital repayments.",
        "Describe the purpose and use of each loan.",
        "Record mixed residential, commercial or private use.",
        "Locate prior unused finance-cost schedules."
      ],
      "downloadHref": "/downloads/guides/landlord-mortgage-interest-tax-relief-checklist.txt"
    },
